#!/usr/bin/env python3
"""Sync public + optional local private agent rules into Codex and Gemini configs."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent
DEFAULT_PUBLIC = REPO_ROOT / "agents" / "GLOBAL.md"
DEFAULT_PRIVATE = Path.home() / ".config" / "agents" / "private.md"
DEFAULT_TARGETS = (
    Path.home() / ".codex" / "AGENTS.md",
    Path.home() / ".gemini" / "GEMINI.md",
)

HEADER = (
    "<!-- Auto-generated by ~/.lki/scripts/sync-agent-rules.py from "
    "public + private agent rules. Do not edit directly. -->\n\n"
)


def render_rules(public_path: Path, private_path: Path | None) -> str:
    """Combine the public rules file and optional private overlay."""
    public_text = public_path.read_text(encoding="utf-8").strip()
    parts = [public_text]
    if private_path is not None and private_path.is_file():
        private_text = private_path.read_text(encoding="utf-8").strip()
        if private_text:
            parts.append(private_text)
    return HEADER + "\n\n".join(parts) + "\n"


def _points_into_repo(target: Path, public_path: Path) -> bool:
    if not target.is_symlink():
        return False
    try:
        resolved_target = target.resolve()
        repo_dir = public_path.resolve().parent.parent
        return resolved_target == repo_dir or repo_dir in resolved_target.parents
    except OSError:
        return False


def sync_targets(
    public_path: Path,
    private_path: Path | None,
    targets: list[Path],
    *,
    check: bool = False,
) -> list[Path]:
    """Write or check rendered rules for all targets. Returns drifted/updated paths."""
    rendered = render_rules(public_path, private_path)
    changed: list[Path] = []
    for target in targets:
        if _points_into_repo(target, public_path):
            raise RuntimeError(f"Refusing to overwrite symlink pointing into public repo: {target}")
        current = target.read_text(encoding="utf-8") if target.is_file() else None
        if current == rendered:
            continue
        changed.append(target)
        if not check:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(rendered, encoding="utf-8")
    return changed


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--public",
        type=Path,
        default=DEFAULT_PUBLIC,
        help="Path to the public global rules Markdown file.",
    )
    parser.add_argument(
        "--private",
        type=Path,
        default=DEFAULT_PRIVATE,
        help="Path to the optional local private rules Markdown file.",
    )
    parser.add_argument(
        "--target",
        dest="targets",
        action="append",
        type=Path,
        help="Destination file path (repeatable). Defaults to Codex and Gemini global files.",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="Check whether targets match rendered rules without modifying files.",
    )
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    targets = args.targets if args.targets else list(DEFAULT_TARGETS)
    if not args.public.is_file():
        print(f"Public rules file not found: {args.public}", file=sys.stderr)
        return 2
    try:
        changed = sync_targets(args.public, args.private, targets, check=args.check)
    except RuntimeError as exc:
        print(str(exc), file=sys.stderr)
        return 2
    if args.check:
        if changed:
            for path in changed:
                print(f"DRIFT: {path}")
            return 1
        print("OK: all targets match rendered rules.")
        return 0
    if changed:
        for path in changed:
            print(f"UPDATED: {path}")
    else:
        print("OK: already up to date.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
